export const THREAD_DEFAULT=Object.freeze({width:3,mode:'outline'});
export function validateThreadAppearance(a){if(a===undefined)return;if(!a||!['thread-appearance-v1','thread-appearance-v2'].includes(a.version)||Object.keys(a).sort().join(',')!=='families,version'||!a.families||Array.isArray(a.families)||Object.keys(a.families).length>8)throw Error('Invalid thread appearance.');for(const [name,v] of Object.entries(a.families)){if(!/^[A-H]$|^foundation$/.test(name)||!v||Object.keys(v).sort().join(',')!==(a.version==='thread-appearance-v2'?'edgeWidth,mode,rank,width':'mode,width')||!['solid','outline'].includes(v.mode)||!Number.isFinite(v.width)||v.width<.5||v.width>30)throw Error('Invalid thread appearance settings.');if(a.version==='thread-appearance-v2'&&(!Number.isInteger(v.rank)||v.rank<1||v.rank>8||!Number.isFinite(v.edgeWidth)||v.edgeWidth<.1||v.edgeWidth>3))throw Error('Invalid family hierarchy or outline weight.');}}
export function threadStyle(a,family){validateThreadAppearance(a);return {...THREAD_DEFAULT,...a?.families[family],mode:'outline'};}
export function threadOpacity(style){return 1-((style.rank||1)-1)*.1;}
export function changeThreadAppearance(a,names,selected,linked,patch){validateThreadAppearance(a);if(!names.includes(selected))throw Error('Select an available thread family.');const result=structuredClone(a||{version:'thread-appearance-v1',families:{}}),extended=result.version==='thread-appearance-v2'||Object.hasOwn(patch,'rank')||Object.hasOwn(patch,'edgeWidth');if(extended){result.version='thread-appearance-v2';for(const name of Object.keys(result.families))result.families[name]={rank:1,edgeWidth:1,...result.families[name]};}for(const name of linked?names:[selected])result.families[name]={...(extended?{rank:1,edgeWidth:1}:{}),...threadStyle(a,name),...patch};validateThreadAppearance(result);return result;}
// Presentation-only miter/bevel ribbon boundary; never feeds certified geometry.
function outlineSides(input,width){const p=input.filter((v,i)=>!i||v.x!==input[i-1].x||v.y!==input[i-1].y);if(p.length<2)return [];const r=width/2,n=p.slice(1).map((b,i)=>{const a=p[i],l=Math.hypot(b.x-a.x,b.y-a.y);return{x:-(b.y-a.y)/l,y:(b.x-a.x)/l}}),side=sign=>p.flatMap((v,i)=>{const a=n[Math.max(0,i-1)],b=n[Math.min(n.length-1,i)],den=1+a.x*b.x+a.y*b.y;if(den>=.5)return[{x:v.x+sign*r*(a.x+b.x)/den,y:v.y+sign*r*(a.y+b.y)/den}];return[{x:v.x+sign*r*a.x,y:v.y+sign*r*a.y},{x:v.x+sign*r*b.x,y:v.y+sign*r*b.y}];});return[side(1),side(-1)];}
export function outlinePoints(input,width){const sides=outlineSides(input,width);return sides.length?[...sides[0],...sides[1].reverse()]:[];}
const unit=(x,y)=>{const length=Math.hypot(x,y);return length?{x:x/length,y:y/length}:null;};
function boundaryContact(point,boundary,tolerance){const points=boundary?.points||[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length],dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy);if(!length)continue;const cross=Math.abs((point.x-a.x)*dy-(point.y-a.y)*dx)/length,dot=(point.x-a.x)*dx+(point.y-a.y)*dy,along=tolerance*length;if(cross<=tolerance&&dot>=-along&&dot<=length*length+along)return true;}return false;}
function tail(point,neighbor,sourceDirection,length){const local=unit(point.x-neighbor.x,point.y-neighbor.y);if(!local)return[];let source=sourceDirection&&unit(sourceDirection.x,sourceDirection.y);if(source&&local.x*source.x+local.y*source.y<0)source={x:-source.x,y:-source.y};source=source||local;const blend=unit(local.x+source.x,local.y+source.y)||local,q1={x:point.x+local.x*length/3,y:point.y+local.y*length/3},q2={x:q1.x+blend.x*length/3,y:q1.y+blend.y*length/3},q3={x:q2.x+source.x*length/3,y:q2.y+source.y*length/3};return[q1,q2,q3];}
export function presentationBleedStrands(strands,boundary,ratio=.1){const points=boundary?.points||[];if(points.length<3)return strands;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),extent=Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));if(!(extent>0)||!(ratio>0))return strands;const length=extent*ratio,tolerance=Math.max(1e-8,extent*1e-8);return strands.map(strand=>{const direction=strand.direction||(strand.p0&&strand.p1?{x:strand.p1.x-strand.p0.x,y:strand.p1.y-strand.p0.y}:null);return{...strand,fragments:strand.fragments.map(fragment=>{const source=fragment.points||[fragment.start,fragment.end];if(source.length<2)return fragment;const next=[...source],startMarked=fragment.startProvenance?.edgeIndexes?.length>0||boundaryContact(source[0],boundary,tolerance),endMarked=fragment.endProvenance?.edgeIndexes?.length>0||boundaryContact(source.at(-1),boundary,tolerance);if(startMarked)next.unshift(...tail(source[0],source[1],direction,length).reverse());if(endMarked)next.push(...tail(source.at(-1),source.at(-2),direction,length));return{...fragment,points:next};})};});}
export function threadPaths(strands,appearance,transform=p=>p){const groups=new Map(),path=points=>points.map((v,i)=>{const q=transform(v);return(i?'L':'M')+q.x+' '+q.y}).join(' ');for(const s of strands){const family=s.family||s.identity?.roleId,style=threadStyle(appearance,family);if(!groups.has(family))groups.set(family,{family,...style,d:'',fragments:0,segments:0});const out=groups.get(family);for(const f of s.fragments){const points=f.points||[f.start,f.end];if(points.length<2)continue;const commands=style.mode==='outline'?outlineSides(points,style.width).map(path):[path(points)];out.d+=(out.d?' ':'')+commands.join(' ');out.fragments++;out.segments+=points.length-1;}}return [...groups.values()];}
export function threadStroke(style){return style.mode==='outline'?Math.min(style.edgeWidth??1,style.width/4):style.width;}
